import { existsSync, readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import type { RecoveryPlayerRecord } from './recovery-data.js';

/** One recovered club whose roster the overlay replaces with an external squad. */
export interface PlayerOverlayClub {
  clubId: number;
  clubName: string;
  sourceClubId: string;
  sourceClubName: string;
  players: number;
}

/**
 * External roster overlay (data/external/player-overlay.json). It is generated by
 * `pnpm data:import-players`; the recovered APK files under data/recovery stay untouched.
 */
export interface PlayerOverlay {
  source: string;
  license: string;
  snapshot: string;
  asOf: string;
  generatedAt: string;
  clubs: PlayerOverlayClub[];
  players: RecoveryPlayerRecord[];
}

export interface AppliedPlayerOverlay {
  players: RecoveryPlayerRecord[];
  clubIds: Set<number>;
  imported: number;
}

function isValidRecord(player: RecoveryPlayerRecord): boolean {
  return typeof player.nameEn === 'string' && player.nameEn.trim().length > 0
    && Number.isInteger(player.clubId)
    && Number.isInteger(player.positionCode) && player.positionCode >= 1 && player.positionCode <= 13
    && Number.isFinite(player.initAge);
}

/**
 * Replaces the recovered roster of every known club the overlay covers with its
 * imported squad (in overlay order). Clubs the overlay does not cover keep the APK rows.
 */
export function applyPlayerOverlay(base: RecoveryPlayerRecord[], overlay: PlayerOverlay | undefined, knownClubIds: ReadonlySet<number>): AppliedPlayerOverlay {
  if (!overlay) return { players: base, clubIds: new Set(), imported: 0 };
  const declared = new Set(overlay.clubs.map((club) => club.clubId).filter((id) => knownClubIds.has(id)));
  const imported = overlay.players.filter((player) => declared.has(player.clubId) && isValidRecord(player));
  // A club is only replaced when at least one valid imported row survives for it.
  const clubIds = new Set(imported.map((player) => player.clubId));
  return { players: [...base.filter((player) => !clubIds.has(player.clubId)), ...imported], clubIds, imported: imported.length };
}

/** Reads the overlay named by PLAYER_OVERLAY_FILE (default data/external/player-overlay.json); `off` disables it. */
export function readPlayerOverlay(path = process.env.PLAYER_OVERLAY_FILE || resolve(process.cwd(), 'data/external/player-overlay.json')): PlayerOverlay | undefined {
  if (path === 'off' || !existsSync(path)) return undefined;
  try {
    const overlay = JSON.parse(readFileSync(path, 'utf8')) as PlayerOverlay;
    if (!Array.isArray(overlay.clubs) || !Array.isArray(overlay.players)) throw new Error('overlay must contain clubs[] and players[]');
    return overlay;
  } catch (error) {
    console.warn(JSON.stringify({ event: 'player_overlay_load_failed', path, error: error instanceof Error ? error.message : String(error) }));
    return undefined;
  }
}
